88	
89	    @Override
90	    @Transactional(readOnly = true)
91	    public Collection<Visit> findAllVisits() throws DataAccessException {
92	        return visitRepository.findAll();
93	    }
94	
95	    @Override
96	    @Transactional
97	    public void deleteVisit(Visit visit) throws DataAccessException {
98	        visitRepository.delete(visit);
99	    }
100	
101	    @Override
102	    @Transactional(readOnly = true)
103	    public Vet findVetById(int id) throws DataAccessException {
104	        return findEntityById(() -> vetRepository.findById(id));
105	    }
106	
107	    @Override
108	    @Transactional(readOnly = true)
109	    public Collection<Vet> findAllVets() throws DataAccessException {
110	        return vetRepository.findAll();
111	    }
112	
113	    @Override
114	    @Transactional
115	    public void saveVet(Vet vet) throws DataAccessException {
116	        vetRepository.save(vet);
117	    }
118	
119	    @Override
120	    @Transactional
121	    public void deleteVet(Vet vet) throws DataAccessException {
122	        vetRepository.delete(vet);
123	    }
124	
125	    @Override
126	    @Transactional(readOnly = true)
127	    public Collection<Owner> findAllOwners() throws DataAccessException {
128	        return ownerRepository.findAll();
129	    }
130	
131	    @Override
132	    @Transactional(readOnly = true)
133	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
134	        if (lastName != null) {
135	            return ownerRepository.findByLastName(lastName, pageable);
136	        }
137	        return ownerRepository.findAll(pageable);
138	    }
139	
140	    @Override
141	    @Transactional
142	    public void deleteOwner(Owner owner) throws DataAccessException {
143	        ownerRepository.delete(owner);
144	    }
145	
146	    @Override
147	    @Transactional(readOnly = true)
148	    public PetType findPetTypeById(int petTypeId) {
149	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
150	    }
151	
152	    @Override
153	    @Transactional(readOnly = true)
154	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
155	        return petTypeRepository.findAll();
156	    }
157	
158	    @Override
159	    @Transactional
160	    public void savePetType(PetType petType) throws DataAccessException {
161	        petTypeRepository.save(petType);
162	    }
163	
164	    @Override
165	    @Transactional
166	    public void deletePetType(PetType petType) throws DataAccessException {
167	        petTypeRepository.delete(petType);
168	    }
169	
170	    @Override
171	    @Transactional(readOnly = true)
172	    public Specialty findSpecialtyById(int specialtyId) {
173	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
174	    }
175	
176	    @Override
177	    @Transactional(readOnly = true)
178	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
179	        return specialtyRepository.findAll();
180	    }
181	
182	    @Override
183	    @Transactional
184	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
185	        specialtyRepository.save(specialty);
186	    }
187	
188	    @Override
189	    @Transactional
190	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
191	        specialtyRepository.delete(specialty);
192	    }
193	
194	    @Override
195	    @Transactional(readOnly = true)
196	    public Collection<PetType> findPetTypes() throws DataAccessException {
197	        return petRepository.findPetTypes();
198	    }
199	
200	    @Override
201	    @Transactional(readOnly = true)
202	    public Owner findOwnerById(int id) throws DataAccessException {
203	        return findEntityById(() -> ownerRepository.findById(id));
204	    }
205	
206	    @Override
207	    @Transactional(readOnly = true)
208	    public Pet findPetById(int id) throws DataAccessException {
209	        return findEntityById(() -> petRepository.findById(id));
210	    }
211	
212	    @Override
213	    @Transactional
214	    public void savePet(Pet pet) throws DataAccessException {
215	        pet.setType(findPetTypeById(pet.getType().getId()));
216	        petRepository.save(pet);
217	    }
218	
219	    @Override
220	    @Transactional
221	    public void saveVisit(Visit visit) throws DataAccessException {
222	        visitRepository.save(visit);
223	
224	    }
225	
226	    @Override
227	    @Transactional(readOnly = true)
228	    public Collection<Vet> findVets() throws DataAccessException {
229	        return vetRepository.findAll();
230	    }
231	
232	    @Override
233	    @Transactional
234	    public void saveOwner(Owner owner) throws DataAccessException {
235	        if (owner.isNew() && owner.getCustomerCode() == null) {
236	            Collection<Owner> existing = ownerRepository.findAll();
237	            owner.assignCustomerCode((int) existing.stream().filter(o -> owner.getCity().equalsIgnoreCase(o.getCity())).count());
238	            owner.assignNamesakeCount(existing);
239	        }
240	        ownerRepository.save(owner);
241	
242	    }
243	
244	    @Override
245	    @Transactional(readOnly = true)
246	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
247	        return ownerRepository.findByLastName(lastName);
248	    }
249	
250	    @Override
251	    @Transactional(readOnly = true)
252	    public Collection<Visit> findVisitsByPetId(int petId) {
253	        return visitRepository.findByPetId(petId);
254	    }
255	
256	    @Override
257	    @Transactional(readOnly = true)
258	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
259	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
260	    }
261	
262	    private <T> T findEntityById(Supplier<T> supplier) {
263	        try {
264	            return supplier.get();
265	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
266	            // Just ignore not found exceptions for Jdbc/Jpa realization
267	            return null;
268	        }
269	    }
270	
271	}
