17	
18	/**
19	 * Computes the Luhn check digit over the digits contained in a string.
20	 */
21	public final class CheckDigits {
22	
23	    private CheckDigits() {
24	    }
25	
26	    /** Return the Luhn check digit (0-9) over the digits contained in {@code s}, or {@code null} when {@code s} is null. */
27	    public static Integer luhn(String s) {
28	        if (s == null) {
29	            return null;
30	        }
31	        int sum = 0;
32	        boolean dbl = true;
33	        for (int i = s.length() - 1; i >= 0; i--) {
34	            char c = s.charAt(i);
35	            if (c < '0' || c > '9') {
36	                continue;
37	            }
38	            int d = c - '0';
39	            if (dbl) {
40	                d *= 2;
41	                if (d > 9) {
42	                    d -= 9;
43	                }
44	            }
45	            sum += d;
46	            dbl = !dbl;
47	        }
48	        return (10 - (sum % 10)) % 10;
49	    }
50	}
