28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private java.time.LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_member_count")
71	    private Integer householdMemberCount;
72	
73	    public String getCustomerCode() {
74	        return this.customerCode;
75	    }
76	
77	    public Integer getNamesakeCount() {
78	        return this.namesakeCount;
79	    }
80	
81	    public void setNamesakeCount(Integer namesakeCount) {
82	        this.namesakeCount = namesakeCount;
83	    }
84	
85	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
86	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
87	        int count = 0;
88	        for (Owner other : existingOwners) {
89	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
90	                && getLastName().equalsIgnoreCase(other.getLastName())) {
91	                count++;
92	            }
93	        }
94	        this.namesakeCount = count;
95	        assignHouseholdMemberCount(existingOwners);
96	    }
97	
98	    public Integer getHouseholdMemberCount() {
99	        return this.householdMemberCount;
100	    }
101	
102	    /** Record how many owners (this one included) share this owner's household after this create. */
103	    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
104	        int count = 1;
105	        for (Owner other : existingOwners) {
106	            if (householdId != null && householdId.equals(other.getHouseholdId())) {
107	                count++;
108	            }
109	        }
110	        this.householdMemberCount = count;
111	    }
112	
113	    public String getHouseholdId() {
114	        return this.householdId;
115	    }
116	
117	    public void setHouseholdId(String householdId) {
118	        this.householdId = householdId;
119	    }
120	
121	    /** Assign the '<CITY3>-<LAST3>-<NNNN>' customer code, where NNNN is one more than {@code cityCount}. */
122	    public void assignCustomerCode(int cityCount) {
123	        String city3 = getCity().substring(0, Math.min(3, getCity().length())).toUpperCase(Locale.ROOT);
124	        String last3 = getLastName().substring(0, Math.min(3, getLastName().length())).toUpperCase(Locale.ROOT);
125	        this.customerCode = String.format("%s-%s-%04d", city3, last3, cityCount + 1);
126	    }
127	
128	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
129	    private Set<Pet> pets;
130	
131	    public java.time.LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    public String getAddress() {
140	        return this.address;
141	    }
142	
143	    /** Store the address normalized so create persists and returns the canonical form. */
144	    public void setAddress(String address) {
145	        this.address = AddressNormalizer.normalize(address);
146	    }
147	
148	    public String getCity() {
149	        return this.city;
150	    }
151	
152	    public void setCity(String city) {
153	        this.city = city;
154	    }
155	
156	    public String getTelephone() {
157	        return this.telephone;
158	    }
159	
160	    /** Store the telephone in E.164 form so create and update persist and return it normalized. */
161	    public void setTelephone(String telephone) {
162	        this.telephone = TelephoneNormalizer.toE164(telephone);
163	    }
164	
165	    public String getPostcode() {
166	        return this.postcode;
167	    }
168	
169	    public void setPostcode(String postcode) {
170	        this.postcode = postcode;
171	    }
172	
173	    public String getEmail() {
174	        return this.email;
175	    }
176	
177	    /** Store the address lower-cased so it is persisted and returned normalized. */
178	    public void setEmail(String email) {
179	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
180	    }
181	
182	    protected Set<Pet> getPetsInternal() {
183	        if (this.pets == null) {
184	            this.pets = new HashSet<>();
185	        }
186	        return this.pets;
187	    }
188	
189	    protected void setPetsInternal(Set<Pet> pets) {
190	        this.pets = pets;
191	    }
192	
193	    public List<Pet> getPets() {
194	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
195	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
196	        return Collections.unmodifiableList(sortedPets);
197	    }
198	
199	    public void setPets(List<Pet> pets) {
200	        this.pets = new HashSet<>(pets);
201	    }
202	
203	    public void addPet(Pet pet) {
204	        getPetsInternal().add(pet);
205	        pet.setOwner(this);
206	    }
207	
208	    /**
209	     * Return the Pet with the given name, or null if none found for this Owner.
210	     *
211	     * @param name to test
212	     * @return true if pet name is already in use
213	     */
214	    public Pet getPet(String name) {
215	        return getPet(name, false);
216	    }
217	
218	    /**
219	     * Return the Pet with the given name, or null if none found for this Owner.
220	     *
221	     * @param name to test
222	     * @return true if pet name is already in use
223	     */
224	    public Pet getPet(String name, boolean ignoreNew) {
225	        name = name.toLowerCase();
226	        for (Pet pet : getPetsInternal()) {
227	            if (!ignoreNew || !pet.isNew()) {
228	                String compName = pet.getName();
229	                compName = compName.toLowerCase();
230	                if (compName.equals(name)) {
231	                    return pet;
232	                }
233	            }
234	        }
235	        return null;
236	    }
237	
238	    public Pet getPet(Integer petId) {
239	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
240	    }
241	
242	    @Override
243	    public String toString() {
244	        return new ToStringCreator(this)
245	
246	            .append("id", this.getId())
247	            .append("new", this.isNew())
248	            .append("lastName", this.getLastName())
249	            .append("firstName", this.getFirstName())
250	            .append("address", this.address)
251	            .append("city", this.city)
252	            .append("telephone", this.telephone)
253	            .toString();
254	    }
255	}
