29	import org.springframework.http.converter.HttpMessageConverter;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.util.Localities;
32	import org.springframework.web.bind.annotation.ControllerAdvice;
33	import org.springframework.web.bind.annotation.ExceptionHandler;
34	import org.springframework.web.bind.annotation.ResponseBody;
35	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdvice;
36	
37	/**
38	 * Rejects a create-owner request whose 4-digit postcode falls outside the range pinned for
39	 * its city's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), responding 400 Bad Request.
40	 * A city with no known region accepts any 4-digit postcode, and an absent postcode is left
41	 * untouched. Malformed postcodes are left to the generic pattern validation. Applies only to
42	 * the create endpoint.
43	 */
44	@ControllerAdvice
45	@Order(Ordered.HIGHEST_PRECEDENCE)
46	public class OwnerPostcodeAdvice implements RequestBodyAdvice {
47	
48	    /** Region -> inclusive {low, high} 4-digit postcode range. */
49	    private static final Map<String, int[]> REGION_RANGE =
50	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
51	
52	    @Override
53	    public boolean supports(MethodParameter methodParameter, Type targetType,
54	                            Class<? extends HttpMessageConverter<?>> converterType) {
55	        Method method = methodParameter.getMethod();
56	        return OwnerFieldsDto.class.equals(targetType) && method != null
57	            && "addOwner".equals(method.getName());
58	    }
59	
60	    @Override
61	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
62	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
63	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
64	        if (isOutOfRange(owner.getPostcode(), owner.getCity())) {
65	            throw new InvalidPostcodeException();
66	        }
67	        return body;
68	    }
69	
70	    private boolean isOutOfRange(String postcode, String city) {
71	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
72	            return false;
73	        }
74	        int[] range = REGION_RANGE.get(Localities.regionFor(city));
75	        if (range == null) {
76	            return false;
77	        }
78	        int value = Integer.parseInt(postcode);
79	        return value < range[0] || value > range[1];
80	    }
81	
82	    @Override
83	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
84	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
85	        return body;
86	    }
87	
88	    @Override
89	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
90	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
91	        return inputMessage;
92	    }
93	
94	    @ExceptionHandler(InvalidPostcodeException.class)
95	    @ResponseBody
96	    public ResponseEntity<Void> handleInvalidPostcode(InvalidPostcodeException e) {
97	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).build();
98	    }
99	
100	    /** Signals that the postcode is out of range for the city's region. */
101	    static class InvalidPostcodeException extends RuntimeException {
102	    }
103	}
