17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.util.Localities.regionFor(owner.getCity(), owner.getPostcode()))")
31	    @Mapping(target = "contactPreference",
32	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "checkDigit",
35	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
39	    default String identityKey(Owner owner) {
40	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
41	    }
42	
43	    default String orEmpty(String value) {
44	        return value == null ? "" : value;
45	    }
46	
47	    /** Numeric level 1-3: starts at 1, +1 for an email, +1 when namesakeCount is 0, capped at 3 (level 4 reserved for tenure). */
48	    default Integer membershipLevel(Owner owner) {
49	        int level = 1;
50	        if (owner.getEmail() != null) {
51	            level++;
52	        }
53	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
54	            level++;
55	        }
56	        return Math.min(level, 3);
57	    }
58	
59	    /** Derive the '<customerCode>-M<YY>' membership number, where YY is the last two digits of the registrationDate year. */
60	    default String membershipNumber(Owner owner) {
61	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
62	            return null;
63	        }
64	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
65	    }
66	
67	    Owner toOwner(OwnerDto ownerDto);
68	
69	    @Mapping(target = "id", ignore = true)
70	    @Mapping(target = "pets", ignore = true)
71	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
72	    @Mapping(target = "registrationDate", expression = "java(effectiveRegistrationDate(ownerDto))")
73	    Owner toOwner(OwnerFieldsDto ownerDto);
74	
75	    /** The supplied registration date, or today's date when absent, rolled forward off weekends to a business day. */
76	    default java.time.LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerDto) {
77	        java.time.LocalDate supplied = ownerDto.getRegistrationDate();
78	        return org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(
79	            supplied != null ? supplied : java.time.LocalDate.now());
80	    }
81	
82	    /** Normalize to E.164 so the create path stores, and duplicate detection compares, that form. */
83	    @Named("normalizeTelephone")
84	    default String normalizeTelephone(String telephone) {
85	        return TelephoneNormalizer.toE164(telephone);
86	    }
87	
88	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
89	
90	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
91	
92	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
93	        OwnerPageDto ownerPageDto = new OwnerPageDto();
94	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
95	        ownerPageDto.setPage(ownerPage.getNumber());
96	        ownerPageDto.setSize(ownerPage.getSize());
97	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
98	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
99	        return ownerPageDto;
100	    }
101	}
